package org.immutables.fixture.pointer;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import org.junit.jupiter.api.Test;

public class PointerValuesTest {
  private static ImmutablePointerValues.Text text(String name) {
    return ImmutablePointerValues.Text.builder().name(name).build();
  }

  private static ImmutablePointerValues.Branch branch() {
    ImmutablePointerValues.Text first = text("first");
    ImmutablePointerValues.Text second = text("second");
    Map<String, PointerValues.Node> named = new LinkedHashMap<>();
    named.put("a/b", first);
    named.put("~", second);
    return ImmutablePointerValues.Branch.builder()
        .name("root")
        .child(first)
        .addChildren(first, second)
        .putAllNamed(named)
        .optional(Optional.of(second))
        .array(first, second)
        .addSet(first)
        .numbers(1, 2)
        .nullable(null)
        .build();
  }

  @Test
  public void parsesAndRenders() {
    PointerValuesPointers.Pointer pointer = PointerValuesPointers.parse("/named/a~1b/name");
    assertThat(PointerValuesPointers.render(pointer)).isEqualTo("/named/a~1b/name");
    assertThat(pointer.toString()).isEqualTo("/named/a~1b/name");
    assertThat(pointer).isEqualTo(PointerValuesPointers.parse("/named/a~1b/name"));
    assertThat(PointerValuesPointers.parse("").toString()).isEmpty();
    assertThat(PointerValuesPointers.parse("/").toString()).isEqualTo("/");
    assertThatThrownBy(() -> PointerValuesPointers.parse("x"))
        .isInstanceOf(PointerValuesPointers.MalformedPointerException.class);
    assertThatThrownBy(() -> PointerValuesPointers.parse("/~2"))
        .isInstanceOf(PointerValuesPointers.MalformedPointerException.class);
  }

  @Test
  public void resolvesValuesAndContainers() {
    ImmutablePointerValues.Branch root = branch();
    assertThat(PointerValuesPointers.resolve(root, PointerValuesPointers.parse(""))).isSameAs(root);
    assertThat(PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/child/name")))
        .isEqualTo("first");
    assertThat(PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/children/1/name")))
        .isEqualTo("second");
    assertThat(PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/named/a~1b/name")))
        .isEqualTo("first");
    assertThat(PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/named/~0/name")))
        .isEqualTo("second");
    assertThat(PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/optional/name")))
        .isEqualTo("second");
    assertThat(PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/array/0/name")))
        .isEqualTo("first");
    assertThat(PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/children")))
        .isSameAs(root.children());
    assertThat(PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/nullable"))).isNull();
  }

  @Test
  public void updatesOnlyTheAddressedPath() {
    ImmutablePointerValues.Branch root = branch();
    ImmutablePointerValues.Branch updated = (ImmutablePointerValues.Branch) PointerValuesPointers.update(
        root, PointerValuesPointers.parse("/children/1/name"), value -> value + "!");

    assertThat(updated).isNotSameAs(root);
    assertThat(updated.child()).isSameAs(root.child());
    assertThat(updated.children().get(0)).isSameAs(root.children().get(0));
    assertThat(updated.children().get(1)).isNotSameAs(root.children().get(1));
    assertThat(updated.named()).isSameAs(root.named());
    assertThat(((PointerValues.Named) updated.children().get(1)).name()).isEqualTo("second!");

    assertThat(PointerValuesPointers.update(
        root, PointerValuesPointers.parse("/child/name"), value -> new String("first")))
        .isSameAs(root);
  }

  @Test
  public void updatesContainersAndElements() {
    ImmutablePointerValues.Branch root = branch();
    ImmutablePointerValues.Branch mapUpdated = (ImmutablePointerValues.Branch) PointerValuesPointers.update(
        root, PointerValuesPointers.parse("/named/~0/name"), value -> "changed");
    assertThat(mapUpdated.named().keySet()).containsExactly("a/b", "~");
    assertThat(mapUpdated.named().get("a/b")).isSameAs(root.named().get("a/b"));

    ImmutablePointerValues.Branch arrayUpdated = (ImmutablePointerValues.Branch) PointerValuesPointers.update(
        root, PointerValuesPointers.parse("/array/1/name"), value -> "changed");
    assertThat(arrayUpdated.array()[0]).isSameAs(root.array()[0]);
    assertThat(arrayUpdated.array()[1]).isNotSameAs(root.array()[1]);

    Object replacement = Arrays.asList(text("replacement"));
    ImmutablePointerValues.Branch listUpdated = (ImmutablePointerValues.Branch) PointerValuesPointers.update(
        root, PointerValuesPointers.parse("/children"), value -> replacement);
    assertThat(listUpdated.children()).hasSize(1);
  }

  @Test
  public void distinguishesMissesAndTypeFailures() {
    ImmutablePointerValues.Branch root = branch();
    assertThatThrownBy(() -> PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/missing")))
        .isInstanceOf(PointerValuesPointers.PointerMissException.class);
    assertThatThrownBy(() -> PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/children/01")))
        .isInstanceOf(PointerValuesPointers.PointerTypeException.class);
    assertThatThrownBy(() -> PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/children/9")))
        .isInstanceOf(PointerValuesPointers.PointerMissException.class);
    assertThatThrownBy(() -> PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/name/x")))
        .isInstanceOf(PointerValuesPointers.PointerTypeException.class);
    assertThatThrownBy(() -> PointerValuesPointers.resolve(root, PointerValuesPointers.parse("/nullable/x")))
        .isInstanceOf(PointerValuesPointers.PointerMissException.class);
    assertThatThrownBy(() -> PointerValuesPointers.update(
        root, PointerValuesPointers.parse("/derived"), value -> value))
        .isInstanceOf(PointerValuesPointers.PointerTypeException.class);
    assertThatThrownBy(() -> PointerValuesPointers.update(
        root, PointerValuesPointers.parse("/set"), value -> value))
        .isInstanceOf(PointerValuesPointers.PointerTypeException.class);
    assertThatThrownBy(() -> PointerValuesPointers.update(
        root, PointerValuesPointers.parse("/name"), value -> 1))
        .isInstanceOf(PointerValuesPointers.PointerTypeException.class);
    assertThatThrownBy(() -> PointerValuesPointers.resolve("not a root", PointerValuesPointers.parse("")))
        .isInstanceOf(IllegalArgumentException.class);
  }
}
