  private static int index(String step, int size) {
    if (step.isEmpty() || step.length() > 1 && step.charAt(0) == '0') {
      throw new PointerTypeException("Expected a zero-based index: " + step);
    }
    long index = 0;
    for (int i = 0; i < step.length(); i++) {
      char character = step.charAt(i);
      if (character < '0' || character > '9') {
        throw new PointerTypeException("Expected a zero-based index: " + step);
      }
      index = Math.min((long) size, index * 10 + character - '0');
    }
    if (index >= size) {
      throw new PointerMissException(step);
    }
    return (int) index;
  }

  private static String decode(String pointer, int start, int end) {
    StringBuilder decoded = new StringBuilder(end - start);
    for (int i = start; i < end; i++) {
      char character = pointer.charAt(i);
      if (character != '~') {
        decoded.append(character);
      } else if (++i == end) {
        throw new MalformedPointerException(pointer);
      } else {
        char escaped = pointer.charAt(i);
        if (escaped == '0') {
          decoded.append('~');
        } else if (escaped == '1') {
          decoded.append('/');
        } else {
          throw new MalformedPointerException(pointer);
        }
      }
    }
    return decoded.toString();
  }

